import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';

/**
 * Types and helpers shared by CharactersTab/ActivityTab/ArenaTab. Split out
 * of the old single 999-line StatsTabs.tsx so each tab can be read and
 * changed in isolation.
 */

export function cacheBust() {
  return Date.now();
}
export function invalidateHomeSliderCache() {
  if (typeof window === 'undefined') return;
  try {
    window.dispatchEvent(new Event('rolevaya:invalidate-home-slider-cache'));
  } catch (_unused) {}
}
export function apiUrl(path) {
  const base = app.forum.attribute('apiUrl');
  return base.replace(/\/$/, '') + path;
}
export function forumBaseUrl() {
  const base = app.forum.attribute('baseUrl') || '';
  return base.replace(/\/$/, '');
}
export function playerName(row) {
  return row.nickname || row.username || "#".concat(row.user_id);
}
export function userProfilePath(userId, username) {
  const user = app.store.getById('users', String(userId));
  if (user) {
    try {
      const routed = app.route.user(user);
      if (routed && typeof routed === 'string') return routed;
    } catch (_unused2) {}
    const profileUrl = user.attribute('profileUrl') || user.attribute('url') || null;
    if (profileUrl && String(profileUrl).trim()) {
      return profileUrl;
    }
    const slug = user.attribute('slug') || user.attribute('username') || username || null;
    if (slug && String(slug).trim()) {
      return "/u/".concat(slug);
    }
  }
  const fallbackSlug = (username || '').trim();
  if (fallbackSlug) return "/u/".concat(fallbackSlug);
  return "/u/".concat(userId);
}
export function userLink(userId, label, username) {
  return m(Link, {
    className: "RolevayaPlayerLink",
    href: userProfilePath(userId, username),
    title: label
  }, label);
}
export function avatarUrl(row) {
  const raw = (row.avatar_url || '').trim();
  if (raw) {
    if (/^(data:|blob:)/i.test(raw)) return raw;
    if (/^https?:\/\//i.test(raw)) return raw;
    const base = forumBaseUrl();
    if (raw.startsWith('/')) return "".concat(base).concat(raw);
    return "".concat(base, "/assets/avatars/").concat(raw);
  }
  const userId = row.user_id;
  if (!userId) return null;
  const user = app.store.getById('users', String(userId));
  const storeUrl = (user == null ? void 0 : user.attribute('avatarUrl')) || null;
  return storeUrl && String(storeUrl).trim() ? storeUrl : null;
}
export function rankClass(i) {
  const suffix = i === 0 ? '1' : i === 1 ? '2' : i === 2 ? '3' : i === 3 ? '4' : '';
  return 'RolevayaRank ' + (suffix ? "RolevayaRank--".concat(suffix) : '');
}

// Shared across all three tabs so the same user isn't fetched twice just
// because they show up on e.g. both the activity and arena leaderboards.
const ensuredUserIds = new Set();
let ensureUsersInflight = false;
export async function ensureUsersLoaded(userIds) {
  const ids = Array.from(new Set(userIds)).filter(id => id && !ensuredUserIds.has(id) && !app.store.getById('users', String(id))).slice(0, 200);
  if (!ids.length || ensureUsersInflight) return;
  ensureUsersInflight = true;
  ids.forEach(id => ensuredUserIds.add(id));
  try {
    // Flarum's /api/users list endpoint has no real "id" filter gambit, so
    // filter:{id:...} silently returns an ambient default listing instead
    // of the requested users. Per-ID singular fetches are what Flarum
    // actually supports for arbitrary IDs.
    //
    // Leaderboards here can list up to 50 rows, so firing 50 requests at
    // once (Promise.all over the whole list) would overwhelm the browser's
    // per-origin connection limit and the server. Fetching in small
    // concurrent batches, with a redraw after each, keeps things reliable
    // while showing frames progressively instead of all-or-nothing at the
    // end.
    const concurrency = 4;
    for (let i = 0; i < ids.length; i += concurrency) {
      const chunk = ids.slice(i, i + concurrency);
      await Promise.all(chunk.map(id => app.store.find('users', String(id)).catch(() => null)));
      m.redraw();
    }
  } finally {
    ensureUsersInflight = false;
  }
}
flarum.reg.add('forumaker-rolevaya', 'forum/components/stats/statsShared', { cacheBust: cacheBust,invalidateHomeSliderCache: invalidateHomeSliderCache,apiUrl: apiUrl,forumBaseUrl: forumBaseUrl,playerName: playerName,userProfilePath: userProfilePath,userLink: userLink,avatarUrl: avatarUrl,rankClass: rankClass, });